  function achievementStatsFor(a){let stats=achievementStats(),baseline=(save.chainStartStats||{})[a.id];if(!baseline)return stats;let adj={...stats};for(let k in baseline){if(typeof adj[k]==='number'&&typeof baseline[k]==='number')adj[k]=Math.max(0,adj[k]-baseline[k]);}return adj;}
  function unlockAchievements(){let prev=new Set(save.unlockedAchievements||[]),claimed=new Set(save.claimedAchievements||[]),unlocked=new Set(prev);ACHIEVEMENTS.forEach(a=>{if(isVisible(a)&&a.test(achievementStatsFor(a)))unlocked.add(a.id)});save.unlockedAchievements=[...unlocked];[...unlocked].filter(id=>!prev.has(id)&&!claimed.has(id)).forEach((id,i)=>{let a=ACHIEVEMENTS.find(x=>x.id===id);if(a)setTimeout(()=>showToast(`🏆 ${a.name} · READY TO CLAIM`,3500),i*600)})}
  function dailyDateKey(){let d=new Date();return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  function dailyHash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
  function dailyPool(){return window.WordOverlordDailyQuests||{easy:[],medium:[],hard:[]}}
  function pickDailyQuest(tier,date){let list=dailyPool()[tier]||[];return list.length?list[dailyHash(date+tier)%list.length]:null}
  function ensureDaily(){let date=dailyDateKey();if(!save.daily||save.daily.date!==date){let ids={};['easy','medium','hard'].forEach(t=>{let q=pickDailyQuest(t,date);if(q)ids[t]=q.id});save.daily={date,ids,progress:{},claimed:false};Object.values(ids).forEach(id=>save.daily.progress[id]=0)}return save.daily}
  function dailyQuest(tier){let d=ensureDaily(),id=d.ids?.[tier];return(dailyPool()[tier]||[]).find(q=>q.id===id)||null}
  function dailyReward(){return['easy','medium','hard'].reduce((sum,t)=>sum+(dailyQuest(t)?.reward||0),0)}
  function dailyProgress(q){let d=ensureDaily();return Math.min(q.target,Number(d.progress?.[q.id])||0)}
  function dailyComplete(){return['easy','medium','hard'].every(t=>{let q=dailyQuest(t);return q&&dailyProgress(q)>=q.target})}
  function dailyCompletedCount(){return['easy','medium','hard'].filter(t=>{let q=dailyQuest(t);return q&&dailyProgress(q)>=q.target}).length}
  function dailyCountdown(){let now=new Date(),end=new Date(now);end.setHours(24,0,0,0);let ms=Math.max(0,end-now),h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000),s=Math.floor(ms%60000/1000);return`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
  function refreshDailyCountdowns(){if(!save.daily?.claimed)return;let left=dailyCountdown(),btn=document.getElementById('wo-daily-claim'),dq=document.getElementById('wo-daily-card-progress'),card=document.querySelector('.wo-campaign-card.dailyquests');if(btn?.classList.contains('countdown'))btn.textContent=`CHECK BACK IN ${left}`;if(dq)dq.innerHTML=`Daily Quests completed<br>Check back in : ${left}`;if(card)card.classList.add('completed')}
  function addDaily(type,value,mode='add'){let d=ensureDaily(),quests=['easy','medium','hard'].map(dailyQuest).filter(Boolean);quests.filter(q=>q.type===type).forEach(q=>{let current=Number(d.progress[q.id])||0;d.progress[q.id]=Math.min(q.target,mode==='max'?Math.max(current,value):current+value)})}
  function runStarsForDaily(){let c=campaign(),ths=c.starThresholds||[0.65,0.80,0.95],max=calcTheoreticalMax(run.level,c);return run.score>=Math.round(max*ths[2])&&run.wrong<=1?3:run.score>=Math.round(max*ths[1])?2:run.score>=Math.round(max*ths[0])?1:0}
